std::vector<int> V = {10, 20, 30, 40, 50};

auto end_it = V.end(); // Points past 50

// Basic usage (Distance defaults to 1)
auto it_50 = std::prev(end_it);
// *it_50 == 50

// Explicit distance (k=3)
auto it_30 = std::prev(end_it, 3);
// *it_30 == 30

// Use with Bidirectional Iterator (e.g., list)
std::list<char> L = {'A', 'B'};
auto it_A = std::prev(L.end(), 2);
// *it_A == 'A'
